    "demo_tag": "▶ Demo",
    "demo_title": "Zobacz FODMAPP w akcji",
    "discl": "FODMAPP zapewnia ogólne wskazówki oparte na badaniach FODMAP. Nie zastępuje profesjonalnej porady medycznej.",
    "cam_tag": "📸 Kamera",
